  nightingale: { name: "Nightingale", glyph: "🕯️" },
  squad: { name: "Squad", glyph: "🎖️" },
  spaceengineers: { name: "Space Engineers", glyph: "🛰️" },
  kf2: { name: "Killing Floor 2", glyph: "🩸" },
