@layer components {
  /* Surfaces */
  .card {
    @apply rounded-2xl border border-white/[0.06] bg-navy-900/70 p-6 backdrop-blur-md;
    box-shadow: 0 1px 0 0 rgb(255 255 255 / 0.03) inset, 0 8px 32px -12px rgb(0 0 0 / 0.5);
  }
  .card-hover {
    @apply transition-all duration-200 hover:border-brand-500/30 hover:bg-navy-850/80;
  }
  .glass {
    @apply rounded-2xl border border-white/[0.08] bg-white/[0.03] backdrop-blur-xl;
  }
  .glow-brand {
    box-shadow: 0 0 40px -8px rgb(111 71 245 / 0.35);
  }
  /* The auth-card glow ring — ported directly from Kodely's PromptHero
     "chasing light" ring (components/marketing/PromptHero.tsx +
     app/globals.css there), recoloured to Nxeon's blue -> violet -> cyan
     family instead of Kodely's pink/purple/orange. Same technique, kept
     intact rather than reinvented:
     - Each layer is a STATIC outer clipper (.glow-clip-a/-b, position, plain
       overflow:hidden, never transforms) containing one OVERSIZED inner
       rotator (.glow-spin-a/-b, a 200%-wide square via SPIN_SQUARE in
       AuthShell.tsx, centered) carrying the conic-gradient background. Only
       the inner rotator spins via plain `transform: rotate()`; being
       oversized, its corners sweeping outside a same-sized box never matter
       because the static outer clipper crops them at every angle.
     - The blur lives on the CLIP element, not the rotating child, because
       filters apply after the element's own overflow:hidden clipping — that
       ordering is what lets the light bleed softly past the clip's edge
       instead of surviving as a hard-edged ring.
     - The card sitting on top (relative z-10, opaque) covers the rotator's
       entire interior, leaving only the outer few px visible as a ring.
     - Entrance fade-in, then a slow ambient pulse picking up from the same
       opacity the fade-in settled on (no jump at the handoff). */
  @keyframes glow-spin {
    to {
      transform: rotate(360deg);
    }
  }
  .glow-spin-a {
    animation: glow-spin 9s linear infinite;
  }
  .glow-spin-b {
    animation: glow-spin 14s linear infinite reverse;
  }
  @keyframes glow-fade-in-a {
    from {
      opacity: 0;
      transform: scale(0.94);
    }
    to {
      opacity: 0.22;
      transform: scale(1);
    }
  }
  @keyframes glow-fade-in-b {
    from {
      opacity: 0;
      transform: scale(0.94);
    }
    to {
      opacity: 0.13;
      transform: scale(1);
    }
  }
  @keyframes glow-pulse-a {
    0%,
    100% {
      opacity: 0.22;
    }
    50% {
      opacity: 0.32;
    }
  }
  @keyframes glow-pulse-b {
    0%,
    100% {
      opacity: 0.13;
    }
    50% {
      opacity: 0.21;
    }
  }
  .glow-clip-a {
    animation:
      glow-fade-in-a 0.8s cubic-bezier(0.16, 1, 0.3, 1) both,
      glow-pulse-a 4.5s ease-in-out 0.8s infinite;
  }
  .glow-clip-b {
    animation:
      glow-fade-in-b 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.1s both,

  .tone-light .card-hover:hover {
    @apply border-brand-500/40 bg-white;
  }
  .tone-light .glass {
    @apply border-slate-200 bg-white/70;
  }
  .tone-light .section-label {
    @apply text-slate-500;
  }
  .tone-light .btn-secondary {
    @apply border-slate-300 bg-white text-slate-800 hover:border-slate-400 hover:bg-slate-50;
  }
  .tone-light .btn-ghost {
    @apply text-slate-600 hover:bg-slate-900/[0.06] hover:text-slate-900;
  }

  /* Reusable hero aura — the dual-radial violet/blue glow that ~10 sub-page
     heroes previously inlined by hand. Sits in an absolutely-positioned layer. */
  .hero-aura {
    background-image:
      radial-gradient(ellipse 70% 60% at 15% 0%, rgb(111 71 245 / 0.20), transparent 70%),
      radial-gradient(ellipse 60% 50% at 90% 10%, rgb(59 130 246 / 0.14), transparent 70%);
  }

  /* Soft violet lift on hover for interactive cards (was inline arbitrary shadow). */
  .lift {
    @apply transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/30;
    &:hover { box-shadow: 0 18px 40px -20px rgb(111 71 245 / 0.45); }
  }

  /* Consistent max-width content rail. */
  .rail {
    @apply mx-auto max-w-6xl px-5 sm:px-6;
  }

  /* Top-nav dropdown trigger button. */
  .nav-trigger {
    @apply inline-flex cursor-pointer items-center gap-1 rounded-lg px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:text-white;
  }
  .nav-trigger.is-open {
    @apply text-white;
  }

  /* Animated gradient underline that wipes in on hover (rocket-style nav). Sits
     inside the px-3 padding so it tracks the label width. */
  .nav-underline {
    position: relative;
  }
  .nav-underline::after {
    content: "";
    position: absolute;
    left: 12px;
    right: 12px;
    bottom: 5px;
    height: 1.5px;
    border-radius: 2px;
    background: linear-gradient(90deg, var(--color-accent-blue), var(--color-brand-400));
    transform: scaleX(0);
    transform-origin: left center;
    transition: transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
  }
  .nav-underline:hover::after,
  .nav-underline:focus-visible::after,
  .nav-underline.is-open::after {
    transform: scaleX(1);
  }
  @media (prefers-reduced-motion: reduce) {
    .nav-underline::after { transition: none; }
  }
}

/* ── Game-landing PREVIEW directions (scoped, additive) ──────────────────────
   Ambient motion helpers used only by components/marketing/gamelanding/* and
   their /preview/game-* routes. Prefixed `pv-` so they can never collide with
   the shipped design system, and every one is disabled under reduced-motion. */
@keyframes pv-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
@keyframes pv-float-slow {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}
@keyframes pv-scan {
  0% { transform: translateY(-8%); opacity: 0; }
  12%, 88% { opacity: 1; }
  100% { transform: translateY(108%); opacity: 0; }
}
@keyframes pv-kenburns {
  0% { transform: scale(1.04) translate3d(0, 0, 0); }
  100% { transform: scale(1.14) translate3d(-2%, -2%, 0); }
}
@keyframes pv-sheen {
  0% { transform: translateX(-130%) skewX(-14deg); opacity: 0; }
  35%, 55% { opacity: 0.6; }
  100% { transform: translateX(240%) skewX(-14deg); opacity: 0; }
}
@keyframes pv-grid-pan {
  0% { background-position: 0 0; }
  100% { background-position: 0 40px; }
}
@keyframes pv-ring {
  0% { stroke-dashoffset: var(--pv-ring-len, 300); }
  100% { stroke-dashoffset: var(--pv-ring-off, 60); }
}
@keyframes pv-glow-breathe {
  0%, 100% { opacity: 0.55; }
  50% { opacity: 0.9; }
}
@keyframes pv-draw {
  from { stroke-dashoffset: 760; }
  to { stroke-dashoffset: 0; }
}

.pv-float { animation: pv-float 6s ease-in-out infinite; }
.pv-float-slow { animation: pv-float-slow 8s ease-in-out infinite; }
.pv-scan { animation: pv-scan 5.2s ease-in-out infinite; }
.pv-kenburns { animation: pv-kenburns 22s ease-in-out infinite alternate; }
.pv-sheen { animation: pv-sheen 6s ease-in-out infinite; }
